      "description": "board dimensions are between 1x1 and 100x100"
    },
    {
      "id": "P4",
      "expression": "1 <= len(word) <= len(board) * len(board[0])",
      "description": "word length is between 1 and the total number of cells in the board"
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "isinstance(return_value, bool)",
      "description": "return_value is a boolean"
    },
    {
      "id": "Q2",
      "expression": "return_value == any(dfs(board, word, i, j) for i in range(len(board)) for j in range(len(board[0])))",
      "description": "return_value is true if the word can be constructed from the board, otherwise false"
    }
  ],
  "invariants": []
}
